mapper.select:
select *
from dc_dailycheck
where m_no=#{m_no} and ch_year_month=#{ch_year_month,jdbcType=DATE}

mapper.update:
update dc_dailycheck
set ch_count=#{ch_count}, ch_end_date=#{ch_end_date,jdbcType=DATE}, ch_point_quantity=#{ch_point_quantity}, po_no=#{po_no,jdbcType=NUMERIC}
where ch_no=#{ch_no}
